INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (1800, 'descripcion', 'Salsa Espinaler en botella de 750 ml: el formato grande de la salsa de aperitivo que nació en una taberna de Vilassar de Mar en los años cincuenta. La receta la ideó Ventureta Roldós, de la familia que lleva la casa, y sigue siendo un secreto: la etiqueta solo declara vinagre, pimentón rojo y especias, sin gluten y con sulfitos. Es el aliño que no puede faltar en el aperitivo del Maresme: unas gotas sobre berberechos, almejas o mejillones recién abiertos, sobre unas patatas chips o unas aceitunas, con un vermut al lado. Aporta muy pocas calorías, unas 7 kcal por 100 ml, así que se puede usar sin miedo. Esta botella sale a cuenta en casas donde el vermut del domingo es sagrado y en barras que la sirven a diario. Agítala antes de servirla, guárdala en un lugar fresco y seco y, una vez abierta, en la nevera.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (1800, 'nota_cata', 'Nariz: vinagre vivo con el aroma tostado y dulce del pimentón rojo y un fondo de especias.
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 1800, '1800-salsa-espinaler-750-ml.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 1800 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5568, 'descripcion', 'Salsa Espinaler de 200 ml en botella de cuello estrecho, la que se ve en las barras de las tabernas de la marca y que deja caer la salsa gota a gota. Es la receta familiar creada en Vilassar de Mar en los años cincuenta por Ventureta Roldós, con vinagre, pimentón rojo y una mezcla de especias que la casa no desvela; no lleva gluten y contiene sulfitos. Su sitio natural es el aperitivo del Maresme: un chorrito sobre una lata de berberechos o de almejas al natural, sobre mejillones, aceitunas o patatas fritas, acompañado de un vermut. El formato pequeño es cómodo para tenerlo en la mesa, para probarla por primera vez o para regalar junto a unas conservas. Agita la botella antes de usarla. Guárdala en un lugar fresco y seco y, cuando la abras, consérvala en la nevera para que mantenga su punto ácido y especiado.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5568, 'nota_cata', 'Nariz: vinagre vivo con el aroma tostado y dulce del pimentón rojo y un fondo de especias.
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5568, '5568-salsa-espinaler-200-ml-botella-de-cuello.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5568 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (3529, 'descripcion', 'Salsa Espinaler Picante en botellín de 92 ml: la salsa de aperitivo de Vilassar de Mar en versión con pimienta de cayena para quien busca más carácter. Parte de la receta clásica de la casa, a base de vinagre, pimentón rojo y especias secretas, y le suma la cayena, que añade un picor progresivo sin tapar el sabor del marisco. No lleva gluten y contiene sulfitos. Funciona muy bien con mejillones, berberechos y almejas en conserva, con unas patatas chips o unas aceitunas, y también para dar vida a una tapa de bravas o a un pescado a la plancha. Con un vermut al lado tienes el aperitivo del Maresme con un punto atrevido. El botellín es práctico para tenerlo a mano o para probarla antes de pasar a formatos mayores. Agítala antes de usarla, guárdala en un lugar fresco y seco y, una vez abierta, en la nevera.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (3529, 'nota_cata', 'Nariz: vinagre y pimentón rojo, con un punto más vivo de pimienta de cayena.
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 3529, '3529-salsa-espinaler-picante-92-ml.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 3529 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (6622, 'descripcion', 'Almejas al natural Espinaler en lata de 111 g (63 g escurridos): almejas pequeñas del Atlántico conservadas en su jugo, solo con agua y sal. La marca las selecciona en costas atlánticas (zona FAO 27, Atlántico Nordeste) y las envasa sin aceites ni salsas, para que la carne mantenga su textura delicada y el sabor limpio a mar. El jugo de la lata es parte del placer: se puede tomar con las almejas o guardar para un arroz, una pasta o un sofrito marinero. Para el aperitivo del Maresme basta con abrir la lata, añadir unas gotas de Salsa Espinaler y acompañarlas de un vermut, unas aceitunas y unas patatas. Son de tamaño pequeño, lo que las hace muy agradecidas para picar y para cocinar. No necesitan preparación. Conserva la lata en un lugar fresco y seco; una vez abierta, tómalas en el momento.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 6622, '6622-almejas-al-natural-espinaler.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 6622 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5827, 'descripcion', 'Berberechos al natural Espinaler 45/55 en lata de 111 g: entre 45 y 55 piezas por lata, depurados en agua de mar y envasados solo con agua y sal. Proceden del Atlántico Nordeste (zona FAO 27) y la marca los escoge por origen, calibre y sabor antes de enlatarlos. La depuración en agua de mar ayuda a que conserven el sabor salino propio del berberecho, y el envasado al natural deja que sea el marisco el protagonista. Por calibre, son de tamaño pequeño según la denominación de la lata: un término medio entre el 35/45 y el 55/65. Pesan 63 g escurridos. La forma típica de tomarlos en el Maresme es recién abiertos, con un buen chorro de Salsa Espinaler, unas patatas chips y un vermut. No necesitan preparación. Guarda la lata en un lugar fresco y seco y, una vez abierta, consúmelos al momento; el jugo también puede aprovecharse para cocinar.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5827, '5827-berberechos-al-natural-espinaler-45-55.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5827 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5828, 'descripcion', 'Berberechos al natural Espinaler 55/65 en lata de 111 g: entre 55 y 65 piezas pequeñas por lata, depurados en agua de mar y conservados con agua y sal. Llegan del Atlántico Nordeste (zona FAO 27) y la marca los clasifica por origen, calibre y sabor antes de envasarlos. Al ser un calibre más menudo que el 45/55 o el 35/45, la lata trae más piezas, ideales para picar con palillo o para añadir a un arroz o una pasta marinera. El envasado al natural respeta el sabor yodado del berberecho, y el líquido de la lata se puede aprovechar en la cocina. El peso escurrido es de 63 g. Para el aperitivo, el ritual del Maresme: abrir la lata, regarla con Salsa Espinaler y acompañarla de patatas fritas, aceitunas y un vermut. No requieren preparación. Conserva la lata en un lugar fresco y seco y, una vez abierta, tómalos enseguida.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5828, '5828-berberechos-al-natural-espinaler-55-65.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5828 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5747, 'descripcion', 'Berberechos al natural Espinaler 35/45 en lata de 111 g: de 35 a 45 piezas medianas, el calibre más grueso de los tres que tenemos de la marca. Son berberechos del Atlántico Nordeste (zona FAO 27), depurados en agua de mar y envasados solo con agua y sal, sin nada que disimule su sabor. Espinaler los elige por origen, calibre y sabor, y los presenta en su lata azul clásica. Menos piezas por lata significa berberechos más carnosos, de los que lucen solos en el plato. El peso escurrido es de 63 g. Se sirven tal cual, recién abiertos, con unas gotas de Salsa Espinaler y un vermut, como se hace en las tabernas del Maresme; también admiten un poco de pimienta o limón. No necesitan preparación. Guarda la lata en un lugar fresco y seco y, una vez abierta, tómalos en el momento; su jugo es un buen fondo para cocinar.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5747, '5747-berberechos-al-natural-espinaler-35-45.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5747 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5750, 'descripcion', 'Mejillones en escabeche Espinaler 10/12 en lata de 111 g: entre 10 y 12 mejillones medianos de batea, cocinados y bañados en un escabeche suave. La marca selecciona el mejillón de bateas del Atlántico Nordeste (zona FAO 27), lo cuece y lo cubre con un escabeche de aceite de girasol, vinagre de vino, sal, especias y aroma natural de escabeche, que supone un 38 % de la lata. El resultado es una conserva equilibrada, ni demasiado ácida ni grasa, con piezas que se comen de un bocado. Pesan 69 g escurridos y no llevan gluten. Es la lata que nunca falta en el aperitivo del Maresme: se sirve tal cual, con unas patatas chips, aceitunas y un vermut, y quien quiera puede añadir unas gotas de Salsa Espinaler. El escabeche sobrante sirve para aliñar una ensalada. No requiere preparación. Guárdala en un lugar fresco y seco y, una vez abierta, consúmela enseguida.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5750, '5750-mejillones-en-escabeche-espinaler-10-12.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5750 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (5749, 'descripcion', 'Navajas al natural Espinaler 5/8 en lata de 110 g: de 5 a 8 piezas conservadas con agua y sal, con sus aceites naturales y todo el sabor de la navaja. Espinaler las pesca y selecciona en su punto óptimo en fondos de arena poco profundos y con mareas amplias del Atlántico Nordeste (zona FAO 27). En la lata aparecen unos aceites naturales propios de la navaja que la marca considera señal de calidad, así que no hay que tirarlos: se pueden beber directamente o usar como base de un fondo, un arroz o un sofrito de pescado y marisco. El peso escurrido es de 63 g. Para el aperitivo, se sirven en la propia lata o en un plato, con unas gotas de Salsa Espinaler y un vermut, junto a unas patatas y unas aceitunas. No necesitan preparación. Guarda la lata en un lugar fresco y seco y, una vez abierta, tómalas al momento.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 5749, '5749-navajas-al-natural-espinaler-5-8.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 5749 AND principal = 1);
INSERT INTO producto_textos (idProducto, tipo, contenido) VALUES (3854, 'descripcion', 'Pack Garbí de Espinaler: lo básico del aperitivo de la casa (berberechos al natural, mejillones en escabeche y aceitunas rellenas), listo para regalar. La marca de Vilassar de Mar lo plantea como la forma más sencilla de montar en casa el aperitivo de sus tabernas: una lata de berberechos, una de mejillones y una de olivas Espinaler, tres productos que se entienden solos. Solo hace falta abrir las latas, servirlas en platitos, añadir unas gotas de Salsa Espinaler sobre el marisco y poner un vermut frío. Es un detalle práctico para una visita, un amigo invisible o para quien quiere descubrir la marca sin comprar formatos grandes. También funciona como base de una cesta: se puede completar con una botella de vermut, unas patatas chips o la propia salsa. Las conservas se guardan en un lugar fresco y seco; una vez abiertas, el marisco se toma en el momento y las aceitunas, en la nevera.') ON DUPLICATE KEY UPDATE contenido = VALUES(contenido), updated_at = NOW();
INSERT INTO producto_fotos (idProducto, foto, principal, orden) SELECT 3854, '3854-pack-garbi-espinaler.jpg', 1, 0 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM producto_fotos WHERE idProducto = 3854 AND principal = 1);
